ACTS = {'v1':'Verse 1 (scenes 1–11)','ch':'Choruses 1–2: the first drop (12–13)','v2':'Verse 2: the distraction (14–21)','raid':'Choruses 3–4: the raid (22–23)','v3':'Verse 3: the cost (24–30)','end':'The turn (31–33)'}
def prompt(n, layer, args, body):
    lay = L[layer].format(**args) if args else L[layer]
    return ' '.join(x for x in (LEAD, lay, body, END) if x)
if __name__ == '__main__':
    rows = [[f'r3{act}', f'A{n:02d}-{c}', f'{n} · {layer} · {lyric[:48]}', prompt(n, layer, args, body), layer]
            for n, act, lyric, layer, args, tx, body in S for c in 'ab']
    old = [r for r in json.loads((HERE / 'moodboard.json').read_text()) if not r[0].startswith('r3')]
    (HERE / 'moodboard.json').write_text(json.dumps(rows + old, indent=1))
    lines = ['| # | Lyric | Layer | Transition out |', '| --- | --- | --- | --- |']
    lines += [f'| {n} | *{lyric}* | {layer} | {tx} |' for n, act, lyric, layer, args, tx, body in S]
    (HERE / 'script-alt.md').write_text('# The Speakeasy Mint ALT: scene map (2026-10-28)\n\nGenerated by `make_rows_r3.py` (full prompts in `moodboard.json`). Same lyrics and story as `../mv-speakeasy-mint/script.md`.\n\n' + '\n'.join(lines) + '\n')
    for n, act, lyric, layer, args, tx, body in S:
        print(f'### {n}\n{prompt(n, layer, args, body)}\n')
